INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('1', '1', 'Pusing berputar, tengkuk terasa kaku dan berat terutama pagi hari.', 'Hipertensi Primer / Esensial Grade 1', 'Pemeriksaan tekanan darah (150/95 mmHg), pemeriksaan fisik kardiovaskular, konseling diet rendah garam.', 'Kontrol rutin tiap 2 minggu. Hindari stres dan kurangi konsumsi garam/gorengan.', '2026-11-02 09:15:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('2', '2', 'Sering merasa haus, sering buang air kecil di malam hari, badan terasa cepat lelah.', 'Diabetes Melitus Tipe 2', 'Pemeriksaan gula darah sewaktu (GDS 215 mg/dL), cek tanda vital, edukasi pola diet karbohidrat kompleks.', 'Diberikan terapi Metformin, jadwalkan cek HbA1c bulan depan.', '2026-11-03 10:00:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('3', '3', 'Anak batuk berdahak disertai pilek 3 hari, sedikit hangat di malam hari.', 'Faringitis Akut & Rinofaringitis pada Anak', 'Pemeriksaan orofaring tampak kemerahan (faring hiperemis), suhu 37.8C, auskultasi dada vesikuler.', 'Tingkatkan asupan cairan hangat, istirahat cukup, dan berikan obat teratur.', '2026-11-04 10:30:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('4', '4', 'Gigi geraham belakang kiri ngilu hebat saat minum dingin atau makan manis.', 'Karies Dentis Profunda dengan Pulpitis Reversibel', 'Sondasi (+), perkusi (-), ekskavasi jaringan karies, penambalan sementara dengan eugenol pasta.', 'Jadwal tumpatan komposit permanen dalam 7 hari jika keluhan ngilu mereda.', '2026-11-05 11:20:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('5', '5', 'Pemeriksaan kehamilan rutin trimester kedua (usia kehamilan 24 minggu), mual sudah berkurang.', 'G2P1A0 Gravida 24 Minggu Janin Tunggal Hidup Intrauterin', 'Palpasi Leopold, auskultasi DJJ 142 dpm (teratur), cek tensi 110/70 mmHg, pengukuran tinggi fundus uteri 21 cm.', 'Kondisi janin baik. Teruskan konsumsi kalsium dan vitamin kehamilan, USG kontrol bulan depan.', '2026-11-05 15:30:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('6', '6', 'Nyeri ulu hati seperti terbakar (heartburn), mual, perut kembung terutama saat terlambat makan.', 'Gastritis Akut Erosif / Dispepsia Fungsional', 'Palpasi nyeri tekan epigastrium (+), auskultasi bising usus normal, konseling jam makan teratur.', 'Hindari kopi, pedas, asam, dan jangan langsung tidur setelah makan.', '2026-11-06 09:45:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('7', '7', 'Gusi bengkak dan berdarah saat menyikat gigi.', 'Gingivitis Marginalis Kronis e.c. Calculus Subgingiva', 'Scaling dan pembersihan karang gigi rahang atas dan bawah, irigasi antiseptik chlorhexidine.', 'Instruksikan cara menyikat gigi yang benar (metode Bass) dan penggunaan dental floss.', '2026-11-07 11:15:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('8', '8', 'Sesak napas ringan setelah terpapar udara dingin dan debu, ada bunyi mengi halus.', 'Asma Bronkial Eksaserbasi Ringan', 'Auskultasi paru didapatkan wheezing ekspirasi minimal, saturasi O2 98%, edukasi penghindaran alergen.', 'Diberikan Salbutamol tablet, kontrol bila sesak bertambah berat.', '2026-11-07 10:40:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('9', '9', 'Demam tinggi mendadak sejak kemarin sore, menggigil, sakit kepala di bagian dahi dan nyeri otot sendi.', 'Febris Akut Suspect Viral Infection / ISPA', 'Pemeriksaan suhu 38.6C, tensi 120/80 mmHg, denyut nadi 88x/menit, pemeriksaan fisik umum lengkap.', 'Diberikan antipiretik dan vitamin. Jika dalam 3 hari demam menetap >38C, periksa darah lengkap (DHF/Widal).', '2026-11-08 09:30:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('10', '10', 'Batuk pilek lendir kehijauan 2 hari, nafsu makan menurun, anak rewel saat malam.', 'Rinofaringitis Akut & Batuk Produktif Anak', 'Auskultasi paru ronkhi (-), wheezing (-), tenggorokan hiperemis sedang, suhu 37.6C.', 'Diberikan sirup batuk herbal dan antibiotik oral dosis anak. Kompres hangat bila demam.', '2026-11-08 10:15:00');
INSERT INTO `rekam_medis` (`id_rekam_medis`, `id_kunjungan`, `keluhan`, `diagnosa`, `tindakan`, `catatan`, `created_at`) VALUES ('11', '11', 'Gigi graham kanan atas berdenyut kencang menjalar ke pipi sejak semalam, sulit tidur.', 'Pulpitis Akut Gigi 16', 'Pemeriksaan intraoral gigi 16 karies profunda, tes vitalitas termal (+), devitalisasi pulpa sementara.', 'Pemberian analgesik & antibiotik profilaksis. Pasien diminta kembali 3 hari lagi untuk perawatan saluran akar.', '2026-11-08 11:30:00');
